Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "One dot per event: change in Steam score (2 weeks after vs 4 weeks before), grouped by event type, with the median as a black tick.",
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "filter": "isValid(datum.change)"
    },
    {
      "joinaggregate": [
        {
          "op": "count",
          "as": "n"
        }
      ],
      "groupby": [
        "type"
      ]
    },
    {
      "calculate": "upper(substring(replace(datum.type, ''_'', '' ''), 0, 1)) + substring(replace(datum.type, ''_'', '' ''), 1) + ''  (n='' + datum.n + '')''",
      "as": "type_label"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rn"
        }
      ],
      "groupby": [
        "type"
      ],
      "sort": [
        {
          "field": "change"
        }
      ]
    },
    {
      "calculate": "'''' + (datum.rn % 5)",
      "as": "lane"
    },
    {
      "calculate": "(datum.change >= 0 ? ''+'' : '''') + format(datum.change, ''.1f'') + '' pp''",
      "as": "change_text"
    },
    {
      "calculate": "isValid(datum.net) ? (datum.net >= 0 ? ''+'' : '''') + format(datum.net, ''.1f'') + '' pp'' : ''pending (control data)''",
      "as": "net_text"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rule",
        "color": "#9AA0A6",
        "strokeDash": [
          3,
          3
        ]
      },
      "encoding": {
        "x": {
          "datum": 0
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 85,
        "opacity": 0.85
      },
      "encoding": {
        "y": {
          "field": "type_label",
          "type": "nominal",
          "title": null,
          "sort": {
            "field": "change",
            "op": "median",
            "order": "ascending"
          },
          "axis": {
            "domain": false,
            "ticks": false,
            "labelPadding": 8,
            "labelFontSize": 12,
            "labelColor": "#1F2328",
            "labelLimit": 220
          }
        },
        "yOffset": {
          "field": "lane",
          "type": "nominal",
          "scale": {
            "paddingOuter": 0.6
          }
        },
        "x": {
          "field": "change",
          "type": "quantitative",
          "title": "Change in Steam score: first 2 weeks vs 4 weeks before (pp)",
          "axis": {
            "tickCount": 8,
            "domain": false,
            "ticks": false,
            "gridColor": "#EEEEEC",
            "labelColor": "#5F6368",
            "labelFontSize": 11,
            "titleColor": "#5F6368",
            "titleFontWeight": "normal",
            "titleFontSize": 11
          }
        },
        "color": {
          "field": "game",
          "type": "nominal",
          "scale": {
            "domain": [
              "Cyberpunk 2077",
              "The Witcher 3"
            ],
            "range": [
              "#A87400",
              "#2F5D8C"
            ]
          },
          "legend": {
            "orient": "top",
            "title": null,
            "labelColor": "#5F6368",
            "symbolType": "circle",
            "labelLimit": 240
          }
        },
        "tooltip": [
          {
            "field": "event",
            "title": "Event"
          },
          {
            "field": "game",
            "title": "Game"
          },
          {
            "field": "date",
            "title": "Date",
            "type": "temporal",
            "format": "%d %b %Y"
          },
          {
            "field": "change_text",
            "title": "Score change"
          },
          {
            "field": "net_text",
            "title": "Net of control games"
          },
          {
            "field": "uplift",
            "title": "Review activity change",
            "format": "+.0%"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#1F2328",
        "thickness": 2.5,
        "size": 30
      },
      "encoding": {
        "y": {
          "field": "type_label",
          "type": "nominal",
          "sort": {
            "field": "change",
            "op": "median",
            "order": "ascending"
          }
        },
        "x": {
          "aggregate": "median",
          "field": "change",
          "type": "quantitative"
        },
        "tooltip": [
          {
            "field": "type_label",
            "title": "Event type"
          },
          {
            "aggregate": "median",
            "field": "change",
            "type": "quantitative",
            "title": "Median change (pp)",
            "format": "+.1f"
          }
        ]
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "background": null
  }
}'
